#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill. Codeks Labs week 0: accounts, keys, migrations.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9
cd "$(dirname "${BASH_SOURCE[0]:-$0}")/.."   # repo root: .env lands here (gitignored)
EVALS_REPO="${EVALS_REPO:-../codeks_evals}"   # sibling checkout of codeksnet/evals
EVALS_ENV="$EVALS_REPO/.env"

# Also persist a value into the evals repo's .env (the CLI there reads SUPABASE_URL, not NEXT_PUBLIC_*).
write_evals_env() {
  [[ -d "$EVALS_REPO" ]] || return 0
  local saved="$ENV_FILE" before=(${WRITTEN_ENV[@]+"${WRITTEN_ENV[@]}"})
  ENV_FILE="$EVALS_ENV" write_env "$1" "$2" >/dev/null
  ENV_FILE="$saved"; WRITTEN_ENV=(${before[@]+"${before[@]}"})
  printf '  %s✓ also%s %s → %s\n' "$GREEN" "$RESET" "$1" "$EVALS_ENV"
}

banner "Codeks Labs · Week 0 setup"

# ── 1. Supabase project and API keys ──────────────────────────────────────
stage "Supabase: project and API keys"
say "One free project holds every demo (one schema per app)."
open_url "https://supabase.com/dashboard/new"
step "Create a project named codeks-labs. Pick the region closest to your Hetzner box."
step "Set a database password and save it somewhere safe; stage 2 needs it."
pause "Wait until the project finishes provisioning, then press Enter."
open_url "https://supabase.com/dashboard/project/_/settings/api"
step "Copy the Project URL (https://<ref>.supabase.co)."
ask NEXT_PUBLIC_SUPABASE_URL "Project URL:"
step "Copy the anon / publishable key."
ask NEXT_PUBLIC_SUPABASE_ANON_KEY "anon key:"
step "Reveal and copy the service_role / secret key. It bypasses RLS: server-side only."
ask_secret SUPABASE_SERVICE_KEY "service_role key:"
write_env NEXT_PUBLIC_SUPABASE_URL "$NEXT_PUBLIC_SUPABASE_URL"
write_env NEXT_PUBLIC_SUPABASE_ANON_KEY "$NEXT_PUBLIC_SUPABASE_ANON_KEY"
write_env SUPABASE_SERVICE_KEY "$SUPABASE_SERVICE_KEY"
write_evals_env SUPABASE_URL "$NEXT_PUBLIC_SUPABASE_URL"
write_evals_env SUPABASE_SERVICE_KEY "$SUPABASE_SERVICE_KEY"

# ── 2. Database URL, migrations, exposed schemas ──────────────────────────
stage "Supabase: apply migrations and expose schemas"
say "Creates the evals, tenants and data schemas. Skips any that already exist."
open_url "https://supabase.com/dashboard/project/_/settings/database"
step "Find the connection string (Session pooler works from anywhere; the page may also have a Connect button)."
step "Copy the URI and put your database password in place of [YOUR-PASSWORD]."
ask_secret DATABASE_URL "Postgres connection URI:"
write_env DATABASE_URL "$DATABASE_URL"

MIGRATIONS=(
  "evals|$EVALS_REPO/supabase/migrations/0001_eval_runs.sql"
  "tenants|apps/tenants/supabase/migrations/0001_tenants.sql"
  "data|apps/data/supabase/migrations/0001_data.sql"
)
if command -v psql >/dev/null 2>&1; then
  if confirm "Apply the three migrations to this database now?"; then
    for m in "${MIGRATIONS[@]}"; do
      schema="${m%%|*}"; file="${m#*|}"
      if [[ ! -f "$file" ]]; then warn "missing $file, skipping $schema"; SKIPPED+=("migration for $schema ($file not found)"); continue; fi
      if [[ "$(psql "$DATABASE_URL" -tAc "select 1 from information_schema.schemata where schema_name='$schema'")" == "1" ]]; then
        say "schema $schema already exists, skipping"; continue
      fi
      if psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -q -f "$file"; then printf '  %s✓ applied%s %s\n' "$GREEN" "$RESET" "$schema"
      else warn "migration for $schema failed (see above)"; SKIPPED+=("migration for $schema failed: fix and re-run"); fi
    done
  else
    SKIPPED+=("migrations not applied: run psql \$DATABASE_URL -f <file> for each, or paste them in the Supabase SQL editor")
  fi
else
  warn "psql not found. Paste each migration into the Supabase SQL editor instead:"
  for m in "${MIGRATIONS[@]}"; do note "  - ${m#*|}"; done
  SKIPPED+=("migrations not applied (no psql): paste the files listed above into the SQL editor")
fi

open_url "https://supabase.com/dashboard/project/_/settings/api"
step "Under the Data API settings, find 'Exposed schemas' and add: evals, tenants, data."
note "If the layout differs, search the settings page for 'Exposed schemas'."
step "Save. The dashboards and the tenant demo cannot read their tables until this is done."
pause "Done saving the exposed schemas? Press Enter."

# ── 3. Seed the tenant demo ───────────────────────────────────────────────
stage "Seed the tenant isolation demo"
say "Creates two fake users (alice@acme.test, bob@globex.test), two tenants and their documents."
if [[ -z "$(_existing DEMO_PASSWORD || true)" ]]; then
  write_env DEMO_PASSWORD "$(openssl rand -base64 24 | tr -d '/+=' | cut -c1-20)"
else
  DEMO_PASSWORD="$(_existing DEMO_PASSWORD)"; say "keeping the DEMO_PASSWORD already in $ENV_FILE"
fi
if confirm "Run the seed script now? (needs pnpm install to have been run)"; then
  if (cd apps/tenants && node --env-file=../../.env --import tsx scripts/seed.mts); then :
  else warn "seed failed (see above)"; SKIPPED+=("tenant seed: pnpm --filter @codeksnet/tenants seed"); fi
else
  SKIPPED+=("tenant seed: run it from apps/tenants after copying .env to .env.local")
fi

# ── 4. Anthropic API key ──────────────────────────────────────────────────
stage "Anthropic: key for the LLM judge"
say "The eval harness judge runs a small model (claude-haiku-5-5); CI needs this key too."
open_url "https://console.anthropic.com/settings/keys"
step "Create a key named codeks-labs-evals. Set a low monthly spend limit in Limits."
ask_secret ANTHROPIC_API_KEY "API key:"
write_env ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"
write_evals_env ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"
set_secret ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"   # referenced by the eval-gate job in .github/workflows/ci.yml

# ── 5. Langfuse ───────────────────────────────────────────────────────────
stage "Langfuse Cloud: traces for the eval harness"
open_url "https://cloud.langfuse.com"
step "Sign up (free Hobby plan), create an organization and a project named codeks-labs."
step "Open the project's Settings → API Keys → Create new API key. Copy both keys now; the secret is shown once."
ask LANGFUSE_PUBLIC_KEY "Public key (pk-lf-...):"
ask_secret LANGFUSE_SECRET_KEY "Secret key (sk-lf-...):"
step "The default host is the EU cloud. If you signed up on the US cloud, enter https://us.cloud.langfuse.com."
ask LANGFUSE_HOST "Host [https://cloud.langfuse.com]:"
LANGFUSE_HOST="${LANGFUSE_HOST:-https://cloud.langfuse.com}"
for kv in "LANGFUSE_PUBLIC_KEY|$LANGFUSE_PUBLIC_KEY" "LANGFUSE_SECRET_KEY|$LANGFUSE_SECRET_KEY" "LANGFUSE_HOST|$LANGFUSE_HOST"; do
  write_env "${kv%%|*}" "${kv#*|}"; write_evals_env "${kv%%|*}" "${kv#*|}"
done

# ── 6. PostHog ────────────────────────────────────────────────────────────
stage "PostHog: project key for demo usage events"
open_url "https://app.posthog.com/settings/project"
step "Copy the Project API key (starts phc_). It is public by design; it ships to the browser."
ask NEXT_PUBLIC_POSTHOG_KEY "Project API key:"
step "Which region is the project on? EU: https://eu.i.posthog.com   US: https://us.i.posthog.com"
ask NEXT_PUBLIC_POSTHOG_HOST "Ingest host [https://eu.i.posthog.com]:"
NEXT_PUBLIC_POSTHOG_HOST="${NEXT_PUBLIC_POSTHOG_HOST:-https://eu.i.posthog.com}"
write_env NEXT_PUBLIC_POSTHOG_KEY "$NEXT_PUBLIC_POSTHOG_KEY"
write_env NEXT_PUBLIC_POSTHOG_HOST "$NEXT_PUBLIC_POSTHOG_HOST"

# ── 7. AWS ────────────────────────────────────────────────────────────────
stage "AWS: account, deploy user, CLI profile"
say "Only the events demo uses AWS. Everything it creates sits inside the free tier."
open_url "https://portal.aws.amazon.com/billing/signup"
step "Create the account (or use one you have). Turn on MFA for the root user right away."
step "IAM → Users → Create user 'labs-deployer' → attach AdministratorAccess (fine for a throwaway demo account)."
step "Open the user → Security credentials → Create access key → use case 'Command Line Interface'."
open_url "https://console.aws.amazon.com/billing/home#/account"
step "On the Account page, enable 'IAM user and role access to Billing information' (needed for the budget alarm)."
pause "Have the access key ID and secret ready? Press Enter to start 'aws configure'."
if command -v aws >/dev/null 2>&1; then
  say "Profile name: codeks-labs. Use region eu-central-1 and output json."
  aws configure --profile codeks-labs
  if aws sts get-caller-identity --profile codeks-labs >/dev/null 2>&1; then
    printf '  %s✓ verified%s credentials for profile codeks-labs\n' "$GREEN" "$RESET"
  else warn "could not verify the profile; re-run 'aws configure --profile codeks-labs'"; SKIPPED+=("AWS profile codeks-labs not verified"); fi
else
  warn "aws CLI not installed (brew install awscli), then run: aws configure --profile codeks-labs"
  SKIPPED+=("AWS CLI profile codeks-labs")
fi
ask ALERT_EMAIL "Email for the \$10 monthly budget alarm:"
write_env AWS_PROFILE "codeks-labs"
write_env ALERT_EMAIL "$ALERT_EMAIL"

# ── 8. Pulumi ─────────────────────────────────────────────────────────────
stage "Pulumi: account, token, stack"
open_url "https://app.pulumi.com/signup"
step "Sign up for the free Individual plan."
open_url "https://app.pulumi.com/account/tokens"
step "Create a personal access token named codeks-labs and copy it."
ask_secret PULUMI_ACCESS_TOKEN "Access token:"
write_env PULUMI_ACCESS_TOKEN "$PULUMI_ACCESS_TOKEN"
if command -v pulumi >/dev/null 2>&1; then
  say "Logging in and creating the 'demo' stack. This does not deploy anything."
  note "Stack config lands in a git-ignored file because it holds your alert email."
  if (cd apps/events/infra \
      && PULUMI_ACCESS_TOKEN="$PULUMI_ACCESS_TOKEN" pulumi login >/dev/null \
      && pulumi stack select demo --create >/dev/null \
      && pulumi config set aws:region eu-central-1 \
      && pulumi config set aws:profile codeks-labs \
      && pulumi config set codeks-labs-events:alertEmail "$ALERT_EMAIL"); then
    printf '  %s✓ stack%s demo configured in apps/events/infra\n' "$GREEN" "$RESET"
  else warn "stack setup failed (see above)"; SKIPPED+=("Pulumi stack: see apps/events/README.md"); fi
else
  warn "pulumi CLI not installed (brew install pulumi)"; SKIPPED+=("Pulumi login and stack init: see apps/events/README.md")
fi
say "To deploy later: cd apps/events/infra && pnpm up   (review the preview before confirming)"

# ── 9. Local env files ────────────────────────────────────────────────────
stage "Copy values into each app's .env.local"
say "Next.js reads env files from the app directory. Each app gets only the keys it uses, not the whole $ENV_FILE."
POSTHOG_KEYS="NEXT_PUBLIC_POSTHOG_KEY|NEXT_PUBLIC_POSTHOG_HOST"
SUPABASE_KEYS="NEXT_PUBLIC_SUPABASE_URL|NEXT_PUBLIC_SUPABASE_ANON_KEY|SUPABASE_SERVICE_KEY"
if confirm "Write apps/*/.env.local (existing files are kept)?"; then
  for entry in "landing|$POSTHOG_KEYS" \
               "evals-dashboard|$POSTHOG_KEYS|$SUPABASE_KEYS" \
               "tenants|$POSTHOG_KEYS|$SUPABASE_KEYS|DEMO_PASSWORD" \
               "data|$POSTHOG_KEYS|$SUPABASE_KEYS" \
               "events|$POSTHOG_KEYS"; do
    app="${entry%%|*}"; keys="${entry#*|}"; target="apps/$app/.env.local"
    if [[ -e "$target" ]]; then say "$target exists, kept"
    else (umask 077 && grep -E "^(${keys})=" "$ENV_FILE" > "$target") && printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$target"; fi
  done
else
  SKIPPED+=("per-app .env.local files: copy the keys each app needs from .env (see .env.example)")
fi
note "The events app gets AWS values from 'pulumi stack output' after the first deploy."
[[ -d "$EVALS_REPO" ]] && note "Evals CLI: cd $EVALS_REPO && set -a && . ./.env && set +a, then run codeks-evals with --supabase --langfuse."
note "Next: deploy wizard (Cloudflare DNS and Coolify apps), then 'pnpm dev' to try everything locally."

finish
}

run_wizard "$@"; exit
